const offer = $('cascade_offer_next').item.json;
const ctx = $('agent_context').item.json;
const zone = 'Europe/Lisbon';
const fmtTime = (iso) => DateTime.fromISO(iso).setZone(zone).toFormat('HH:mm');
const dayWord = (iso) => {
  const d = DateTime.fromISO(iso).setZone(zone).startOf('day');
  const today = DateTime.now().setZone(zone).startOf('day');
  const diff = Math.round(d.diff(today, 'days').days);
  if (diff === 0) return 'hoje';
  if (diff === 1) return 'amanhã';
  return DateTime.fromISO(iso).setZone(zone).toFormat('dd/MM');
};
const clinic = ctx.clinic_name || 'a clínica';
const patient = (offer.patient && offer.patient.name) || (ctx.patient && ctx.patient.name) || '';
const firstName = patient ? patient.split(' ')[0] : '';
const doctor = offer.freed_slot.doctor_name || '';
// Exact, pre-formatted facts. The model must copy these verbatim.
const freedClause = dayWord(offer.freed_slot.start_time) + ' às ' + fmtTime(offer.freed_slot.start_time);
let facts = 'Vaga que abriu: ' + freedClause + (doctor ? (' com ' + doctor) : '') + '.';
if (offer.candidate_slot && offer.candidate_slot.start_time) {
  facts += ' Marcação atual do paciente: ' + dayWord(offer.candidate_slot.start_time) + ' às ' + fmtTime(offer.candidate_slot.start_time) + '.';
  facts += ' Objetivo: perguntar de forma simpática se prefere trocar a marcação atual por esta vaga mais cedo.';
} else {
  facts += ' O paciente está em lista de espera. Objetivo: perguntar de forma simpática se tem interesse nesta vaga.';
}
const system = 'É rececionista da ' + clinic + ', em Portugal, e escreve como uma pessoa real: cordial, natural e breve. '
  + 'Português europeu formal ("você"). Nunca se apresenta nem inventa um nome. '
  + (firstName ? ('Trate o paciente por "' + firstName + '". ') : '')
  + 'Escreva UMA mensagem curta (1-2 frases) que oferece a vaga e convida a uma resposta livre e natural '
  + '(por ex. "diga-me se lhe convém" ou "é só responder"). NUNCA peça um formato rígido tipo "responda SIM ou NÃO". '
  + 'REGRA ABSOLUTA: copie horas, datas e nomes EXATAMENTE como aparecem nos factos abaixo; nunca invente nem altere um número. '
  + 'Termine sempre com: Responda STOP para não receber mais mensagens. '
  + 'Responda APENAS com o texto da mensagem.';
return { json: { conversation_id: offer.conversation_id, system_prompt: system, user_prompt: facts } };
